UPDATE takkle.players AS p SET
  first_name = c.first_name,
  last_name = c.last_name,
  college_name = c.college_name,
  source_school = c.college_name,
  conference = coalesce(c.conference, p.conference),
  height_inches = coalesce(c.height_inches, p.height_inches),
  weight_lbs = coalesce(c.weight_lbs, p.weight_lbs),
  source_name = 'ESPN College Football Player Profile',
  source_url = c.source_url,
  last_verified_at = c.verified_at::timestamptz
FROM corrections c
WHERE p.id = c.id::uuid AND p.status = 'unclaimed'
  AND p.source_name = 'ESPN Transfer Portal Rankings';
